package sithclanplugin.managers;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Inject;
import com.google.inject.Singleton;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import sithclanplugin.util.SithClanConstants;

@Slf4j
@Singleton
public class SithClanFileManager
{

    @Inject
    private Gson gson;

    private final File localDirectory;
    private final File storedScheduleFile;
    private final File storedSubscriptionsFile;
    private ArrayList<String> cachedSubscriptions = null;

    private static final String EVENT_LOG_FILE_EXTENTION = ".txt";

    public SithClanFileManager()
    {
        this.localDirectory = new File(RuneLite.RUNELITE_DIR, SithClanConstants.LOCAL_DIRECTORY_NAME);
        this.storedScheduleFile = new File(localDirectory, SithClanConstants.STORED_SCHEDULE_NAME);
        this.storedSubscriptionsFile = new File(localDirectory, SithClanConstants.STORED_SUBSCRIPTIONS_NAME);
    }

    /**
     * SCHEDULE FUNCTIONS
     */

    /**
     * Check if user has a saved event schedule file to load
     * 
     * @return boolean has local schedule file
     */
    public boolean hasSavedSchedule()
    {
        return storedScheduleFile.length() > 0;
    }

    /**
     * Save event schedule to local file
     * 
     * @param data
     *                 String JSON schedule
     */
    public void saveScheduleLocally(String data)
    {
        log.info("Saving schedule to file..");
        try (FileWriter fileWriter = new FileWriter(storedScheduleFile))
        {
            // write data to file
            fileWriter.write(data);
            log.info("Schedule saved successfully.");
        } catch (Exception e)
        {
            log.error("Exception while saving schedule to file: {}", e.getMessage(), e);
        }
    }

    /**
     * Get event schedule from local file
     * 
     * @return String JSON schedule
     */
    public String readScheduleFile()
    {
        try
        {
            log.info("Reading schedule from file..");
            // read schedule from file
            String jsonSchedule = Files.readString(storedScheduleFile.toPath(), StandardCharsets.UTF_8);
            return jsonSchedule.isBlank() ? null : jsonSchedule;
        } catch (Exception e)
        {
            log.error("Exception while reading schedule from file: {}", e.getMessage(), e);
            return null;
        }
    }

    /**
     * Save list of event subscriptions
     * 
     * @param subscriptions
     *                          ArrayList<String> list of event subscriptions to be
     *                          save
     */
    private void saveSubscriptions(ArrayList<String> subscriptions)
    {
        try (FileWriter fileWriter = new FileWriter(storedSubscriptionsFile))
        {
            // write subscriptions to file
            fileWriter.write(gson.toJson(subscriptions));
        } catch (Exception e)
        {
            log.error("Exception while saving event subscriptions: {}", e.getMessage(), e);
        }
    }

    /**
     * Get list of saved or cached event subscriptions
     * 
     * @return ArrayList<String> list of subscribed events
     */
    private ArrayList<String> loadSubscriptions()
    {
        // return cached subscriptions
        if (cachedSubscriptions != null)
        {
            return cachedSubscriptions;
        }
        try
        {
            // load subscriptions from file
            String input = Files.readString(storedSubscriptionsFile.toPath(), StandardCharsets.UTF_8);

            if (input.isBlank())
            {
                cachedSubscriptions = new ArrayList<>();
                return cachedSubscriptions;
            }
            Type listType = new TypeToken<ArrayList<String>>()
            {
            }.getType();
            cachedSubscriptions = gson.fromJson(input, listType);
            return cachedSubscriptions;
        } catch (Exception e)
        {
            log.error("Exception while loading event subscriptions: {}", e.getMessage(), e);
            return new ArrayList<>();
        }
    }

    /**
     * Add new event subscription
     * 
     * @param eventTitle
     *                       String title of event
     */
    public void addSubscription(String eventTitle)
    {
        ArrayList<String> subscriptions = loadSubscriptions();
        if (!subscriptions.contains(eventTitle))
        {
            subscriptions.add(eventTitle);
            saveSubscriptions(subscriptions);
        }
    }

    /**
     * Remove event subscription
     * 
     * @param eventTitle
     *                       String title of event
     */
    public void removeSubscription(String eventTitle)
    {
        ArrayList<String> subscriptions = loadSubscriptions();
        subscriptions.remove(eventTitle);
        saveSubscriptions(subscriptions);
    }

    /**
     * Check if user is subscribed to event
     * 
     * @param eventTitle
     *                       String title of event
     * @return boolean whether event is subscribed
     */
    public boolean isSubscribed(String eventTitle)
    {
        ArrayList<String> subscriptions = loadSubscriptions();
        return subscriptions.contains(eventTitle);
    }

    /**
     * ATTENDANCE FUNCTIONS
     */

    /**
     * Read Clan Event Attendance file
     * 
     * @param file
     *                 File event log file to read
     * @return String assembled event log text
     */
    public String readAttendanceFile(File file)
    {
        try
        {
            // read file as string
            return Files.readString(file.toPath(), StandardCharsets.UTF_8);
        } catch (IOException e)
        {
            log.error("Failed to read attendance file '{}'", file.getName(), e);
            return null;
        }
    }

    /**
     * Read most recent Clan Event Attendance file
     *
     * @return String file contents, or null on failure
     */
    public String readLatestAttendanceFile()
    {
        // TODO: CUSTOM ERROR MESSAGES FOR STATUS LABEL
        // get clan event attendance directory
        File dir = new File(RuneLite.RUNELITE_DIR, SithClanConstants.CLAN_EVENT_ATTENDANCE_DIR);

        // if directory doesn't exist
        if (!dir.exists() || !dir.isDirectory())
        {
            log.warn("Attendance directory not found: {}", dir.getAbsolutePath());
            return null;
        }

        // list all .txt files
        File[] files = dir.listFiles((d, name) -> name.endsWith(EVENT_LOG_FILE_EXTENTION));

        if (files == null || files.length == 0)
        {
            log.warn("No attendance files found in {}", dir.getAbsolutePath());
            return null;
        }

        // sort files by latest first
        File latest = Arrays.stream(files)
                .max(Comparator.comparingLong(File::lastModified))
                .orElse(null);

        if (latest == null)
        {
            return null;
        }

        log.info("Reading latest attendance file: {}", latest.getName());
        return readAttendanceFile(latest);
    }

    /**
     * MISC FUNCTIONS
     */

    /**
     * Create plugin specific files and directories
     * 
     * @throws IOException
     */
    public void initializeFiles() throws IOException
    {
        // main plugin directory
        if (!localDirectory.exists())
        {
            localDirectory.mkdirs();
        }

        // saved event schedule file
        if (!storedScheduleFile.exists())
        {
            storedScheduleFile.createNewFile();
        }

        // event subscriptions file
        if (!storedSubscriptionsFile.exists())
        {
            storedSubscriptionsFile.createNewFile();
        }
    }
}

