     */
    private void showErrorMessage(String errorMessage)
    {
        statusLabel.setForeground(ColorScheme.BRAND_ORANGE);
        statusLabel.setText(errorMessage);
        SithClanUtil.statusTimer(statusLabel);
    }

    /**
