@Slf4j
@Singleton
public class SithClanSenatePanel extends JPanel
{
    @Inject
    private ScheduledExecutorService executor;

    @Inject
    private SithClanEventSchedule eventSchedule;

    @Inject
    private SithClanMemberRoster memberRoster;

